---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class AdvertInfo : IDataInfo
local AdvertInfo = class("AdvertInfo", IDataInfo)
---@type AdvertConfig
local AdvertConfig = T(Global, "AdvertConfig")
---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")
---@type RewardUtil
local RewardUtil = T(Global, "RewardUtil")
---@type TaskUtil
local TaskUtil = T(Global, "TaskUtil")
---@type SAdvertPkSender
local SAdvertPkSender = T(Global, "PidPacketSender")
---@type uuid
local uuid = require "engine_base.util.uuid"

function AdvertInfo:onCreate()
    ---key, defValue, toSelf, toOther, saveDB
    local cfgs = AdvertConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        self:initKey(Define.AdvertInfoKey.DayTimes .. cfg.tag, 0, true, false, cfg.dayMaxTimes >= 0)
        self:initKey(Define.AdvertInfoKey.CoolingTime .. cfg.tag, 0, true, false, cfg.coolingTime > 0)
    end
    self.callbacks = {}
    uuid.randomseed(os.time())
end

---@param player SBasePlayer
function AdvertInfo:onPlayerReady(player)
    if isClient then
        return
    else
        local cfgs = AdvertConfig:getAllCfgs()
        for _, cfg in pairs(cfgs) do
            if string.find(cfg.tag, Define.AdvertTag.FreeReward) then
                self:registerAdCallback(cfg.tag, function(_, _)
                    local rewardId, _ = string.gsub(cfg.tag, Define.AdvertTag.FreeReward, "")
                    rewardId = tonumber(rewardId) or 0
                    RewardUtil:doRewards(player, { { rewardId } })
                end)
            end
        end
        SAdvertPkSender:onGetWatchAdCache(player)
        player.info:addKeyObserver(Define.PlayerInfoKey.LoginDay, function()
            self:reset()
        end)
        if not player.info:getValue(Define.PlayerInfoKey.NewDayLogin) then
            return
        end
        for _, cfg in pairs(cfgs) do
            self:setValue(Define.AdvertInfoKey.DayTimes .. cfg.tag, 0)
        end
    end
end

function AdvertInfo:reset()
    local cfgs = AdvertConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        self:setValue(Define.AdvertInfoKey.DayTimes .. cfg.tag, 0)
        self:setValue(Define.AdvertInfoKey.CoolingTime .. cfg.tag, 0)
    end
end

function AdvertInfo:canWatchAdvert(tag)
    local cfg = AdvertConfig:getCfgByTag(tag)
    if not cfg then
        return false
    end
    if self:getCoolingTime(tag) > 0 then
        return false
    end
    if cfg.dayMaxTimes >= 0 and self:getValue(Define.AdvertInfoKey.DayTimes .. tag) >= cfg.dayMaxTimes then
        return false
    end
    if isClient then
        if isTest then
            return true
        end
        return ClientHelper.getBoolPrefs("ShowVideoAd")
    else
        return true
    end
end

function AdvertInfo:getCoolingTime(tag)
    return math.max(0, self:getValue(Define.AdvertInfoKey.CoolingTime .. tag) - os.time())
end

function AdvertInfo:getAdLastTimes(tag)
    local cfg = AdvertConfig:getCfgByTag(tag)
    if not cfg then
        return 0, 1
    end
    local times = self:getValue(Define.AdvertInfoKey.DayTimes .. tag)
    return math.max(0, cfg.dayMaxTimes - times), cfg.dayMaxTimes
end

---@param callback fun(player : SBasePlayer, params : table | nil)
function AdvertInfo:registerAdCallback(tag, callback)
    self.callbacks[tag] = callback
end

function AdvertInfo:tryWatchAdvert(tag, params)
    local cfg = AdvertConfig:getCfgByTag(tag)
    if not cfg then
        return
    end
    if not self:canWatchAdvert(tag) then
        UIHelper.showToast(Lang:getString("gui.ad.loading.hint"))
        return
    end
    if cfg.slots > 0 then
        local inventory = PlayerManager:getClientPlayer():getPlayerInventory()
        if inventory:getEmptySlotCount() < cfg.slots then
            UIHelper.showInventoryFullTip()
            return
        end
    end
    params = params or {}
    if type(params) ~= "table" then
        LogUtil.logError("AdvertInfo:tryWatchAdvert, params must table.")
        return
    end
    params.ad_type = cfg.type
    params.ad_game = "g1048"
    params.ad_uuid = uuid()
    local builder = DataBuilder.new():fromTable(params)
    ClientHelper.onWatchAd(cfg.id, builder:getData())
    ReportEvent.reportEvent(Game:getPlatformUserId(), "ad_game_clicked", false, {
        item_id = cfg.id,
        source = cfg.type,
    })
end

---@param player SBasePlayer
function AdvertInfo:onWatchAdvert(player, id, params)
    if isClient then
        return
    end
    local builder = DataBuilder.new():fromData(params)
    SAdvertPkSender:onWatchAdSuccess(player, builder:getParam("ad_uuid"))
    local cfg = AdvertConfig:getCfgById(id)
    if not cfg then
        return
    end
    if not self:canWatchAdvert(cfg.tag) then
        return
    end
    if cfg.dayMaxTimes >= 0 then
        self:incValue(Define.AdvertInfoKey.DayTimes .. cfg.tag, 1)
    end
    if cfg.coolingTime > 0 then
        self:setValue(Define.AdvertInfoKey.CoolingTime .. cfg.tag, os.time() + cfg.coolingTime)
    end
    if player.activity then
        player.activity:runServerFunc(0, "onWatchAdvert", id, params)
    end
    TaskUtil:watchAdvert(player, id)
    local callback = self.callbacks[cfg.tag]
    if not callback then
        return
    end
    callback(player, builder:toTable())
    ReportEvent.reportEvent(player.userId, "ad_game_rewarded", false, {
        item_id = id,
        source = cfg.type,
    })
end

return AdvertInfo